import * as Notifications from 'expo-notifications';
import {useEffect,useState} from 'react';
import {Text,View} from 'react-native';
Notifications.setNotificationHandler({handleNotification:async()=>({shouldShowAlert:true,shouldPlaySound:true,shouldSetBadge:false})});
export default function Push(){
  const[t,setT]=useState('');
  useEffect(()=>{(async()=>{const p=await Notifications.requestPermissionsAsync();if(!p.granted)return;
    const x=await Notifications.getExpoPushTokenAsync();setT(x.data);})();},[]);
  return(<View style={{padding:24}}><Text selectable>{t}</Text></View>);}
